:root {
  --bg-primary: #0d1117;
  --bg-panel: #161b22;
  --border: #30363d;
  --text-primary: #e6edf3;
  --text-muted: #8b949e;
  --accent-yellow: #ecad0a;
  --accent-blue: #209dd7;
  --accent-purple: #753991;
  --up: #22c55e;
  --down: #ef4444;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
}

body {
  overflow: hidden;
}

.price-up {
  color: var(--up);
}

.price-down {
  color: var(--down);
}

.panel {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: 6px;
}

button {
  font: inherit;
  cursor: pointer;
}

input,
select {
  font: inherit;
  color: var(--text-primary);
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 4px 8px;
}

